from author_library import *
cards=[]
cards.append(compact('hu_ming','胡明','胡明是在开罗大学任教的考古学家，熟悉亚洲和古埃及材料，与卫斯理长期相识，也是胡说的叔叔。他对古物的热情远胜于日常排场，仍喜欢旧车，却能为一件被别人随意处理的器物惋惜不已。《盗墓》里，他以学者身份对盗墓者保持口头距离，实际又知道病毒、齐白的线索，专业追求与取材伦理之间并不完全清白。到了《废墟》，这位常被朋友说会舍美女而奔向木乃伊的人，认真爱上法国女校长田青丝。他取得其支离破碎的童年记录，深入海岛山顶调查，忧虑爱人会重演母亲遭族规逼死的悲剧；同时又被李规范的计划利用，成为引来卫斯理的中间人。他善于辨析口音、建筑与历史，却明确不懂武术，无法凭学问控制那些隐居高手。事后他急于到法国与田青丝相见，后在《毒誓》仍从埃及为同行汉烈米转达请求，学术关系继续把他卷入奇事。卡片保留博学、古物迷恋、交友和恋爱后的担忧，不把考古猜想当成已证实历史，也不把接触盗墓、外星现象转化成个人法术。','《毒誓》仍在埃及活动并联系同行与卫斯理；与田青丝的关系以《废墟》确证经历为准','重要配角','认识古代文明并保护珍视的人与研究线索','谈到古物眼睛发亮，喜欢亲自查看文物，面对感情则有些忸怩','重要线索或爱人遭威胁时主动调查求助，也会因急切隐瞒来意','研究者应区分材料、推测与亲身技能，朋友的身手不能替代自己判断',[ab('考古与古文研究','分析古器物、文稿、建筑、口音和历史背景，并有跨地同行联系','未掌握全部历史真相，对武术一窍不通；盗墓来源也会带来偏差'),ab('学术与私人联络','为病毒、齐白及汉烈米等线索安排接触，邀请卫斯理核查','联系人可拒绝或隐瞒，机构关系不是无限资源')],[ev('056',762,770,'教授身份与取材伦理'),ev('056',895,929,'古物兴趣和实际判断'),ev('072',2481,2615,'历史推断、恋情与不懂武术'),ev('083',2261,2293,'后续埃及联络汉烈米')],profile='expert',aliases=['胡明教授','胡明博士']))
cards.append(compact('tian_qingsi','田青丝','田青丝是法国女子学校的校长，也是海岛隐居七姓群体与当地人所生的女儿。她小时候不懂母亲的冷淡与秘密，独自上山找从未了解的父亲，遭粗暴对待后仍躲着不见母亲，希望顺着寻女过程找到父亲。她亲眼看到母亲在外祖母逼迫下咬破戒指、倒地变色，却无法理解族规和死亡的全部含义，随后被带到山顶的六角屋子生活。那里的人没有把她当自己人，只有外祖母照顾并教她缓慢呼吸；这种孤立延续约十五年，成为她后来断续记录的噩梦。外祖母临终不反对她逃走，她最终离开并建立新的生活，不能因为血统便假定继承了七姓全套武艺。与胡明恋爱后，她仍想查明自身来历，参与通过他引来卫斯理、帮助结束封闭生活的计划，已不只是被动等待拯救的受害者。卡片保留童年记忆的不完整、自责和后来的教育职业，不将儿童当时的迟疑判成固定冷酷人格。她会慎重决定何时讲述过去，也可帮助后来者在了解传统时保有选择生活的自由。','《废墟》已逃离山顶并任法国女校长，与胡明恋爱，协助下山计划','主角','理解自己的来处并保有离开旧秩序后的自主生活','有教育者的日常秩序，对童年往事则片段式叙述，未必愿被催问','旧事可能伤及自身或学生时谨慎求助，决定合作后能主动安排联络','血缘不等于归属和服从，过去的恐惧不能替别人决定现在',[ab('静坐呼吸法','外祖母传授缓慢呼吸，可长时间静坐','只确证呼吸与静坐，未学会完整武术、轻功或攻击法'),ab('记忆记录与教育联络','记录童年经历和房屋图形，以校长身份在外界生活并与胡明合作','记忆碎片并非全知族史，校务资源不等于战斗装备')],[ev('072',1240,1354,'童年悲剧及山顶生活'),ev('072',2531,2575,'身份、十五年孤立和逃亡'),ev('072',2595,2615,'主动要求调查及技能界限'),ev('072',3026,3033,'协助李规范计划')],profile='ordinary'))
cards.append(compact('qingsi_mother','田青丝的母亲','田青丝的母亲出身海岛山顶隐居的七姓群体，曾违背传统与当地男子相爱离开，生下有两种血缘的女儿。女儿记忆中的她高大美丽、常像冰一样沉默，似乎无法表露温情；可当女孩失踪，她仍不断上山逐人询问，进入粗暴男子聚集的地方寻找。遭人伸手侮辱时，她以极快手法制服对方，显露原本隐藏的武功，村人的恐惧又使她更像传说中的异类。真正让她无路可走的不是这些外人，而是自己的母亲与祖训：两人先争论，后请求多一天寻找女儿仍被拒，她只能望向山下，咬破一直戴着的戒指，在女儿眼前倒下。原文通过儿童视角呈现这场死亡，后来人物据此确认族规逼死的意义，却没有交代她与丈夫之间所有往事。卡片保留为了爱离开、为了女儿返回，以及最终无法摆脱强制秩序的矛盾，不能因她表情冷淡便否认关切，也不能把被迫自尽说成自由接受惩罚。后日谈采用最后可行动的成人形态并保留终局记忆，戒中毒物不是必须携带或必然重演的剧本。','《废墟》回忆线中被族规与母亲逼迫自尽；参战恢复最后可行动形态并保留终局记忆','主角','寻找并保护女儿，同时争取原本被族群否认的私人生活','沉默压抑，感情常藏在反复寻找与细小动作里','身体遭侵犯会迅速反制；面对亲族权威却有根深蒂固的畏惧','亲情与族规会形成冲突，不能把外在服从自动当作内心认同',[ab('家传近身武术','以迅疾手法擒制冒犯者，长期隐匿真实身手','仅以具体近身表现衡量，没有飞行、超远程攻击或不死之身'),ab('寻人和地方行动','独自沿山路询问并追寻失踪女儿','不知道女儿躲藏位置，家庭秘密也限制沟通')],[ev('072',1084,1135,'寻女、外观与反制'),ev('072',1240,1289,'最后争论和死亡'),ev('072',2543,2544,'身世与私奔')],profile='martial'))
cards[-1]['adaptations'].append({'change':'恢复最后可行动形态并保留终局记忆，未默认携带自尽毒物','reason':'让已故人物在新关系中选择，避免强制重演原悲剧。','power_impact':'仅恢复身体，不新增反抗心控或诅咒的能力。'})
cards.append(compact('qingsi_grandmother','田青丝的外祖母','田青丝的外祖母是七姓隐居群体中的老人，满脸皱纹、声音嘶哑，身体看似枯老，却能背着挣扎的孩子飞快登山、越过大石。她痛恨女儿出走，把多年思念说成血肉相连的剧痛，却又在再次见面时以规矩逼女儿走向死亡；她转身发抖，显示执行强制并没有让自己免于痛苦。随后她带走外孙女，在黑暗房间中限制孩子活动，又成为整个群体中唯一持续照料、传授呼吸法的人。这样的照料不能抵销先前造成的伤害，却说明她并非只为残酷而行动，而是把亲情牢牢塞进自己无法摆脱的秩序。到临终，她终于承认别人始终不把女孩当自己人，告诉她若要逃走，自己并不反对，只提醒被发现会遭杀害。卡片保留这一迟来的松动，不把她改造成早就暗中策划自由的慈祥老人，也不固定成永不改变的脸谱反派。她在新场景中的冲突应围绕维护家族、恐惧失去亲人与是否继续强迫后辈展开，古老武艺仅是实现行动的工具，不能让其道德判断自动正确。','《废墟》回忆线中年老临终，允许外孙女自行逃离；参战恢复最后可行动的老年形态并保留终局记忆','阶段性对立者','维持亲族与祖训所定义的秩序，同时害怕再次失去后人','严厉寡言，以命令安排晚辈，却会在独处或别过脸时显露痛苦','家族规定被触犯时曾逼亲人赴死；确认后辈永远无法归属后会有限放手','自称为了家人仍可能伤害家人，改变不能抹去既有责任',[ab('老年家传武术','背负孩子快速攀山、越障，伸手制住外孙女，并能教授静坐呼吸','衰老身体仍会死亡，没有永葆巅峰或远程点穴证据'),ab('封闭环境中的照护与教习','在群体排斥中照料外孙女并传授有限本领','照护与控制并存，不能替女孩决定所有关系和未来')],[ev('072',1173,1207,'老态与越障能力'),ev('072',1240,1315,'逼女儿及强行带走外孙女'),ev('072',2563,2575,'照护、教习和临终放行')],profile='martial'))
cards[-1]['adaptations'].append({'change':'恢复最后可行动的老年形态并保留终局记忆','reason':'原作只记临终许可，后日谈须说明恢复接口。','power_impact':'不返老还童，不增加年轻时未展示的本领。'})
cards.append(compact('li_guifan','李规范','李规范是七姓后裔的年轻首领，面貌丑陋、大头浓眉，年纪不过十五六岁，却能在山路上以深厚武功让卫斯理全力追随。他的地位有世袭背景，思想却不愿困在先人的失败和隐居誓言中；在他看来，那座六角建筑和世代生活已经成为恶梦。他筹划三年，借田青丝、胡明和陈长青祖屋的关联引来卫斯理，希望获得现代社会中的支持，也为先人遗骸寻找合适安排。牛一山率人阻挠时，他一度被制，却能在脱困后以领袖气度约束众人，同时坚持内部秘密不该由外人随便窥看。最终大多数族人选择离开，他安排少年入学、成年者分散生活，自己也承认离山后只剩名义上的统领，不能约束每个人做什么。后日谈中他不认为参与外国军事政变必然是为非作歹，仍保留与现代普遍准则不同的祖辈豪气。卡片既保留改革封闭生活的决心，也保留维护权威、保密和对本族行动宽容的一面，不把他写成全然温和的学生领袖，更不替原文揭开没有正式说出的祖先身份。','《废墟》率族人离山，散居后为名义首领，继续守秘密并自行参与世事',['主角','阶段性对立者'],'让族人离开代代重复的隐居生活并保留自尊和传承','在同龄人气质与首领威严间切换，好学而善于提前布局','内部挑战时维持权威，外人越界追问时坚决划线','可以打破隐居规矩而仍保留秘密，离开后不能假装仍控制每个人',[ab('深厚家传武术','快速攀越陡崖、持久赶路，出手和落地稳健','是人类武术，不能飞行或对抗整支现代军队'),ab('长期迁居与教育安排','筹划资金、联络和学校，促成自愿下山并定期聚会','依赖家族财富和各人同意，散居后实际号令力有限')],[ev('072',1808,1857,'身手、厌恶旧生活与受袭'),ev('072',2404,2430,'威严与保密边界'),ev('072',2863,2894,'主动结束隐居'),ev('072',3022,3079,'长期计划和学业'),ev('072',3240,3269,'终局名义统领与政变观念')],profile='martial'))
cards.append(compact('niu_yishan','牛一山','牛一山是海岛七姓后裔中坚持祖训的一派领头人，中年而深沉，行进迅疾，连从旁掠过也运劲防备。他把世代隐居与忠于老皇爷的遗训视为不可分割，认为李规范推动离山已经越界，便安排人用大幕制住少年与访客，再要求卫斯理带胡明离开、忘记他们的存在。武功和严密观察使他具有真实威胁，但保密执念也会令他失措：一句泄露老皇爷称呼的话，就足以让他急着把责任推给胡隆。与支持离山者争执后，他最终说愿去者去、愿留者留，表面承认选择，实际却不能承受所有人都走的结果。众人离开时，他独留建筑中，怒斥不肖子孙并纵火自尽；容易延烧的旧建筑在大火中化作废墟，尸体无法寻回。卡片保留他对祖辈遭遇的忠诚、对变迁的恐惧和对别人实施控制的责任，不把死亡写成守传统必然正确的证明。参战采用最后可行动的中年形态并保留终局记忆，使他可以重新面对留下是否仍有意义，而不预设每次失败都必须赴火。','《废墟》独留祖居纵火自尽；参战恢复最后可行动形态并保留终局记忆','阶段性对立者','保存隐居祖业与秘密，避免自己成为背弃祖先的一代','行事沉稳防备，言语常以规矩和集体忠诚施压','秩序被挑战时先拘束和驱逐，支持尽失后曾走向毁灭自己与祖屋','个人忠诚不能自动代表所有族人愿望，也无法让旧生活免于变化',[ab('家传内外功与控制战术','迅疾移动、运劲戒备，组织大幕突袭和集体近战','依赖同伴与地形，正面控制并非必胜；没有超自然结界'),ab('隐居派组织','以祖训凝聚保守族人并安排隔离访客','支持会流失，最终没有人陪他留守；无法强制内心忠诚')],[ev('072',1857,1899,'大幕突袭'),ev('072',2185,2239,'内劲和要求驱逐'),ev('072',2340,2378,'保密压力与推责'),ev('072',3082,3107,'终局火毁和死亡')],profile='martial'))
cards[-1]['adaptations'].append({'change':'恢复最后可行动形态并保留终局记忆','reason':'保留死亡后果而容许重新面对选择，不固定重演自尽。','power_impact':'不恢复祖屋或已失去的追随者。'})
cards.append(compact('hu_long','胡隆','胡隆是七姓隐居群体中身形高大、声如洪钟的武者，支持年轻首领李规范离开祖居，反对牛一山以祖训之名将首领拘禁。他带人进入大厅，大声责斥对方犯上，语言不算细致，忠诚却直接通过行动表现。可在众人争吵中一提到老皇爷，原本与牛一山对立的他又立刻与对方一起喊永不泄密，封住卫斯理去路，说明他的改革支持仍有绝对的秘密边界。他急着要求访客说清知道了什么，遭卫斯理反讽便出手擒拿，动作虽外形粗笨，手腕变化、力道和反应都相当扎实；连续攻势却被卫斯理巧劲击中手腕而中断。李规范一声命令便使他退下，他没有因个人怒气挑战承认的首领。终局随多数族人离山，后续单独生涯未被详细叙述，不能把全族参与的每件奇事都归在他名下。卡片保留护主、好胜和暴躁，也让他能在新的生活中学习不用武力回答所有秘密问题；支持离山并不代表已经自动接受外界的一切规范。','《废墟》参与支持离山的一派，随多数族人走入外界，具体后续未详','阶段性对立者','保护认可的首领并维护家族核心秘密','说话直来直去，情绪高时声势很大，遇明确命令能收手','觉得秘密被窥探或尊严遭讥讽时迅速逼近动手','支持改变生活不等于放弃所有界线，但对外人动手也会造成新的冲突',[ab('近身擒拿与家传武术','腕手变向迅速、力道强，连续爪抓进攻','曾被卫斯理击腕化解；只按近身搏斗，不赋予鬼术'),ab('护主协作','带人解除内部拘禁并服从李规范命令','判断易受怒气与祖训牵动，不能代表所有族人')],[ev('072',2320,2346,'入场护主与共同保密'),ev('072',2360,2414,'动手技巧、被解及服从')],profile='martial'))
save(cards)
